125→    pub async fn publish_file_metadata(
126→        api: &cipherbox_api_client::ApiClient,
127→        file_meta: &cipherbox_core::FileMetadata,
128→        folder_key: &[u8],
129→        file_ipns_private_key: &zeroize::Zeroizing<Vec<u8>>,
130→        file_ipns_name: &str,
131→        coordinator: &crate::PublishCoordinator,
132→    ) -> Result<(), String> {
133→        let folder_key_arr: [u8; 32] = folder_key.try_into()
134→            .map_err(|_| "Invalid folder key length for FileMetadata encryption".to_string())?;
135→
136→        let sealed = cipherbox_core::folder::encrypt_file_metadata(file_meta, &folder_key_arr)
137→            .map_err(|e| format!("FileMetadata encryption failed: {}", e))?;
138→
139→        let iv_hex = hex::encode(&sealed[..12]);
140→        use base64::Engine;
141→        let data_base64 = base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
142→        let json = serde_json::json!({ "iv": iv_hex, "data": data_base64 });
143→        let json_bytes = serde_json::to_vec(&json)
144→            .map_err(|e| format!("FileMetadata JSON serialization failed: {}", e))?;
145→
146→        let file_meta_cid = cipherbox_api_client::ipfs::upload_content(api, &json_bytes)
147→            .await.map_err(|e| format!("{}", e))?;
148→
149→        let seq = coordinator.resolve_sequence(api, file_ipns_name).await?;
150→
151→        let ipns_key_arr: [u8; 32] = file_ipns_private_key.as_slice().try_into()
152→            .map_err(|_| "Invalid file IPNS private key length".to_string())?;
153→        let new_seq = seq + 1;
154→        let value = format!("/ipfs/{}", file_meta_cid);
155→        let record = cipherbox_core::create_ipns_record(&ipns_key_arr, &value, new_seq, 86_400_000)
156→            .map_err(|e| format!("File IPNS record creation failed: {}", e))?;
157→        let marshaled = cipherbox_core::marshal_ipns_record(&record)
158→            .map_err(|e| format!("File IPNS record marshal failed: {}", e))?;
159→
160→        let record_b64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
161→
162→        let req = cipherbox_api_client::IpnsPublishRequest {
163→            ipns_name: file_ipns_name.to_string(),
164→            record: record_b64,
165→            metadata_cid: file_meta_cid.clone(),
166→            encrypted_ipns_private_key: None,
167→            key_epoch: None,
168→            expected_sequence_number: None,
169→        };
170→        match cipherbox_api_client::ipns::publish_ipns(api, &req).await.map_err(|e| format!("{}", e))? {
171→            cipherbox_api_client::PublishResult::Success => {}
172→            cipherbox_api_client::PublishResult::Conflict { .. } => {
173→                log::warn!("Unexpected conflict on per-file IPNS publish for {}", file_ipns_name);
174→            }
175→        }
176→
177→        coordinator.record_publish(file_ipns_name, new_seq);
178→        log::info!("Per-file IPNS publish succeeded for {}", file_ipns_name);
179→        Ok(())
180→    }
