 15→/// Check if WinFsp filesystem driver is installed on Windows.
 16→///
 17→/// Queries the Windows Registry (HKLM\SOFTWARE\WinFsp) for the install directory
 18→/// and verifies the winfsp-x64.dll exists at the expected path.
 19→/// Returns true if WinFsp is installed and the DLL is present.
 20→#[cfg(target_os = "windows")]
 21→fn check_winfsp_installed() -> bool {
 22→    use winreg::enums::*;
 23→    use winreg::RegKey;
 24→    let hklm = RegKey::predef(HKEY_LOCAL_MACHINE);
 25→    // WinFsp is a 32-bit installer, so on 64-bit Windows the registry key
 26→    // lives under WOW6432Node. Try the native path first, then WOW6432Node.
 27→    let subkeys = [
 28→        "SOFTWARE\\WinFsp",
 29→        "SOFTWARE\\WOW6432Node\\WinFsp",
 30→    ];
 31→    for subkey in &subkeys {
 32→        if let Ok(key) = hklm.open_subkey(subkey) {
 33→            if let Ok(dir) = key.get_value::<String, _>("InstallDir") {
 34→                let dll_path = std::path::Path::new(&dir).join("bin").join("winfsp-x64.dll");
 35→                if dll_path.exists() {
 36→                    return true;
 37→                }
 38→            }
 39→        }
 40→    }
 41→    false
 42→}
