 85→    let app_state = AppState::new(&api_base_url, dev_key);
 86→
 87→    tauri::Builder::default()
 88→        .plugin(tauri_plugin_deep_link::init())
 89→        .plugin(tauri_plugin_autostart::init(
 90→            // MacosLauncher param is macOS-specific; on Windows the plugin
 91→            // uses Registry HKCU\...\Run automatically (param is ignored).
 92→            tauri_plugin_autostart::MacosLauncher::LaunchAgent,
 93→            None,
 94→        ))
 95→        .plugin(tauri_plugin_shell::init())
 96→        .plugin(tauri_plugin_notification::init())
 97→        .manage(app_state)
 98→        .setup(|app| {
 99→            // Hide dock icon -- menu bar only (pure background utility)
100→            #[cfg(target_os = "macos")]
101→            app.set_activation_policy(tauri::ActivationPolicy::Accessory);
102→
103→            // Check WinFsp runtime is available on Windows
104→            #[cfg(target_os = "windows")]
105→            {
106→                if !check_winfsp_installed() {
107→                    log::error!("WinFsp not found. Virtual filesystem will not be available.");
108→                    // Show a dialog warning the user. The app can still launch
109→                    // (tray, settings work) but mount will fail gracefully.
110→                    use tauri_plugin_notification::NotificationExt;
111→                    let _ = app.notification()
112→                        .builder()
113→                        .title("CipherBox - WinFsp Not Found")
114→                        .body(
115→                            "WinFsp filesystem driver is not installed. CipherBox requires \
116→                             WinFsp to mount your encrypted vault. Please reinstall CipherBox \
117→                             or install WinFsp manually from https://winfsp.dev"
118→                        )
119→                        .show();
120→                }
121→            }
122→
123→            // Build the system tray menu bar icon
124→            let handle = app.handle().clone();
125→            tray::build_tray(&handle)
126→                .map_err(|e| {
127→                    log::error!("Failed to build tray: {}", e);
128→                    let boxed: Box<dyn std::error::Error> = e.into();
129→                    tauri::Error::Setup(boxed.into())
130→                })?;
131→
132→            // Initial tray status: NotConnected
133→            let _ = tray::update_tray_status(&handle, &tray::TrayStatus::NotConnected);
134→
135→            // In dev-key mode, auto-create the login webview so the JS auth
136→            // flow runs immediately without user interaction.
137→            #[cfg(debug_assertions)]
138→            {
139→                let state = handle.state::<AppState>();
140→                if state.dev_key.blocking_read().is_some() {
141→                    log::info!("Dev-key mode: auto-creating login webview");
142→                    let _ = tauri::WebviewWindowBuilder::new(
143→                        app,
144→                        "main",
145→                        tauri::WebviewUrl::App("index.html".into()),
146→                    )
147→                    .title("CipherBox")
148→                    .inner_size(480.0, 600.0)
149→                    .center()
150→                    .resizable(false)
151→                    .visible(false)
152→                    .on_page_load(|_webview, payload| {
153→                        log::info!(
154→                            "Webview page load: url={}, event={:?}",
155→                            payload.url(),
156→                            payload.event()
157→                        );
158→                    })
159→                    .build()
160→                    .map_err(|e| {
161→                        log::error!("Failed to create dev-key webview: {}", e);
162→                    });
163→                }
164→            }
165→
166→            log::info!("CipherBox Desktop setup complete (tray icon active)");
167→            Ok(())
168→        })
169→        .on_window_event(|window, event| {
170→            // Hide the login window on close instead of destroying it.
171→            // The app is a menu-bar utility — only "Quit" from tray should exit.
172→            if let WindowEvent::CloseRequested { api, .. } = event {
173→                if window.label() == "main" {
174→                    api.prevent_close();
175→                    let _ = window.hide();
176→                }
177→            }
178→        })
179→        .invoke_handler({
180→            #[cfg(debug_assertions)]
181→            {
182→                tauri::generate_handler![
183→                    commands::handle_auth_complete,
184→                    commands::handle_session_restore,
185→                    commands::try_silent_refresh,
186→                    commands::logout,
187→                    commands::start_sync_daemon,
188→                    commands::open_oauth_popup,
189→                    commands::get_dev_key,
190→                    commands::handle_test_login_complete,
191→                    commands::log_js_error,
192→                ]
193→            }
194→            #[cfg(not(debug_assertions))]
195→            {
196→                tauri::generate_handler![
197→                    commands::handle_auth_complete,
198→                    commands::handle_session_restore,
199→                    commands::try_silent_refresh,
200→                    commands::logout,
201→                    commands::start_sync_daemon,
202→                    commands::open_oauth_popup,
203→                ]
204→            }
205→        })
206→        .run(tauri::generate_context!())
207→        .expect("error while running CipherBox Desktop");
208→}
