  1→//! System tray icon and menu for CipherBox Desktop.
  2→//!
  3→//! Creates a tray icon with status display and actions:
  4→//! Open CipherBox, Sync Now, Login/Logout, Quit.
  5→//!
  6→//! On macOS: runs as a pure background utility (no Dock icon).
  7→//! On Windows: runs as a system tray icon in the notification area.
  8→
  9→pub mod status;
 10→
 11→pub use status::TrayStatus;
 12→
 13→use std::sync::atomic::{AtomicU32, Ordering};
 14→use tauri::menu::{MenuBuilder, MenuItemBuilder, PredefinedMenuItem};
 15→use tauri::tray::TrayIconBuilder;
 16→use tauri::{AppHandle, Manager};
 17→
 18→/// Counter for unique popup window labels.
 19→static POPUP_COUNTER: AtomicU32 = AtomicU32::new(0);
 20→
 21→/// ID used to look up the single tray icon instance.
 22→const TRAY_ID: &str = "cipherbox-tray";
 23→
 24→/// Build and register the system tray icon with an initial NotConnected menu.
 25→///
 26→/// Menu items:
 27→/// - `status`: Disabled informational line showing current status
 28→/// - `open`: Open ~/CipherBox in file manager (enabled when mounted)
 29→/// - `sync`: Trigger immediate sync (enabled when connected)
 30→/// - separator
 31→/// - `login`: Show Web3Auth webview (when not connected)
 32→/// - `logout`: Unmount + clear keys (when connected)
 33→/// - separator
 34→/// - `quit`: Unmount if mounted, then exit
 35→pub fn build_tray(app: &AppHandle) -> Result<(), String> {
 36→    let menu = build_menu(app, &TrayStatus::NotConnected)?;
 37→
 38→    #[cfg(target_os = "macos")]
 39→    let tray_icon = tauri::image::Image::from_bytes(include_bytes!("../../icons/tray-icon@2x.png"))
 40→        .map_err(|e| format!("Failed to load tray icon: {}", e))?;
 41→    #[cfg(target_os = "windows")]
 42→    let tray_icon = tauri::image::Image::from_bytes(include_bytes!("../../icons/icon.ico"))
 43→        .map_err(|e| format!("Failed to load tray icon: {}", e))?;
 44→    #[cfg(not(any(target_os = "macos", target_os = "windows")))]
 45→    let tray_icon = tauri::image::Image::from_bytes(include_bytes!("../../icons/tray-icon-linux@2x.png"))
 46→        .map_err(|e| format!("Failed to load tray icon: {}", e))?;
 47→
 48→    let _tray = TrayIconBuilder::with_id(TRAY_ID)
 49→        .menu(&menu)
 50→        .show_menu_on_left_click(true)
 51→        .tooltip("CipherBox")
 52→        .icon(tray_icon)
 53→        .icon_as_template(cfg!(target_os = "macos"))
 54→        .on_menu_event(move |app, event| {
 55→            handle_menu_event(app, event.id().as_ref());
 56→        })
 57→        .build(app)
 58→        .map_err(|e| format!("Failed to build tray icon: {}", e))?;
 59→
 60→    log::info!("System tray icon created");
 61→    Ok(())
 62→}
 63→
 64→/// Build the tray menu with item states matching the given status.
 65→fn build_menu(
 66→    app: &AppHandle,
 67→    status: &TrayStatus,
 68→) -> Result<tauri::menu::Menu<tauri::Wry>, String> {
 69→    let status_text = format!("Status: {}", status.label());
 70→    let is_mounted = matches!(status, TrayStatus::Syncing | TrayStatus::Synced);
 71→    let is_syncable = matches!(status, TrayStatus::Synced | TrayStatus::Error(_));
 72→    let is_disconnected = matches!(status, TrayStatus::NotConnected);
 73→    let is_connected = status.is_connected();
 74→
 75→    let status_item = MenuItemBuilder::with_id("status", &status_text)
 76→        .enabled(false)
 77→        .build(app)
 78→        .map_err(|e| format!("Failed to build status item: {}", e))?;
 79→
 80→    let open_item = MenuItemBuilder::with_id("open", "Open CipherBox")
 81→        .enabled(is_mounted)
 82→        .build(app)
 83→        .map_err(|e| format!("Failed to build open item: {}", e))?;
 84→
 85→    let sync_item = MenuItemBuilder::with_id("sync", "Sync Now")
 86→        .enabled(is_syncable)
 87→        .build(app)
 88→        .map_err(|e| format!("Failed to build sync item: {}", e))?;
 89→
 90→    let login_item = MenuItemBuilder::with_id("login", "Login...")
 91→        .enabled(is_disconnected)
 92→        .build(app)
 93→        .map_err(|e| format!("Failed to build login item: {}", e))?;
 94→
 95→    let logout_item = MenuItemBuilder::with_id("logout", "Logout")
 96→        .enabled(is_connected)
 97→        .build(app)
 98→        .map_err(|e| format!("Failed to build logout item: {}", e))?;
 99→
100→    let quit_item = MenuItemBuilder::with_id("quit", "Quit CipherBox")
101→        .build(app)
102→        .map_err(|e| format!("Failed to build quit item: {}", e))?;
103→
104→    let sep1 = PredefinedMenuItem::separator(app)
105→        .map_err(|e| format!("Failed to build separator: {}", e))?;
106→    let sep2 = PredefinedMenuItem::separator(app)
107→        .map_err(|e| format!("Failed to build separator: {}", e))?;
108→
109→    MenuBuilder::new(app)
110→        .item(&status_item)
111→        .item(&open_item)
112→        .item(&sync_item)
113→        .item(&sep1)
114→        .item(&login_item)
115→        .item(&logout_item)
116→        .item(&sep2)
117→        .item(&quit_item)
118→        .build()
119→        .map_err(|e| format!("Failed to build menu: {}", e))
120→}
121→
122→/// Handle a menu item click by ID.
123→fn handle_menu_event(app: &AppHandle, id: &str) {
124→    use tauri_plugin_notification::NotificationExt;
125→    match id {
126→        "open" => {
127→            // Open ~/CipherBox in the platform file manager
128→            let mount_point = dirs::home_dir()
129→                .map(|h| h.join("CipherBox"))
130→                .unwrap_or_default();
131→            if !mount_point.exists() {
132→                log::warn!("Mount point {} does not exist — filesystem may not be mounted", mount_point.display());
133→                // Show notification instead of a confusing file manager error
134→                if let Err(e) = app.notification()
135→                    .builder()
136→                    .title("CipherBox")
137→                    .body("Vault is not mounted. Please sign in first.")
138→                    .show()
139→                {
140→                    log::error!("Failed to show notification: {}", e);
141→                }
142→                return;
143→            }
144→            #[cfg(target_os = "macos")]
145→            {
146→                if let Err(e) = std::process::Command::new("open")
147→                    .arg(mount_point.to_str().unwrap_or("~/CipherBox"))
148→                    .spawn()
149→                {
150→                    log::error!("Failed to open CipherBox in Finder: {}", e);
151→                }
152→            }
153→            #[cfg(target_os = "windows")]
154→            {
155→                if let Err(e) = std::process::Command::new("explorer.exe")
156→                    .arg(mount_point.to_str().unwrap_or_default())
157→                    .spawn()
158→                {
159→                    log::error!("Failed to open CipherBox in Explorer: {}", e);
160→                }
161→            }
162→            #[cfg(target_os = "linux")]
163→            {
164→                if let Err(e) = std::process::Command::new("xdg-open")
165→                    .arg(mount_point.to_str().unwrap_or_default())
166→                    .spawn()
167→                {
168→                    log::error!("Failed to open CipherBox in file manager: {}", e);
169→                }
170→            }
171→        }
172→        "sync" => {
173→            // Trigger immediate sync via the SyncDaemon channel stored in AppState
174→            let state = app.state::<crate::state::AppState>();
175→            if let Some(tx) = state.sync_trigger.read().ok().and_then(|g| g.clone()) {
176→                let _ = tx.try_send(());
177→                log::info!("Manual sync triggered");
178→            } else {
179→                log::warn!("Sync trigger channel not available");
180→            }
181→        }
182→        "login" => {
183→            // Show existing window or create a new one with on_new_window
184→            // handler for OAuth popups.
185→            if let Some(window) = app.get_webview_window("main") {
186→                // Reload page to reset stale DOM & Web3Auth state after logout
187→                let _ = window.eval("location.reload()");
188→                let _ = window.show();
189→                let _ = window.set_focus();
190→            } else {
191→                log::info!("Creating login webview window");
192→                match tauri::WebviewWindowBuilder::new(
193→                    app,
194→                    "main",
195→                    tauri::WebviewUrl::App("index.html".into()),
196→                )
197→                .title("CipherBox")
198→                .inner_size(480.0, 600.0)
199→                .center()
200→                .resizable(false)
201→                .on_new_window({
202→                    let app_handle = app.clone();
203→                    move |url, features| {
204→                        // Create popup with shared WKWebViewConfiguration so
205→                        // window.opener is preserved for OAuth postMessage callbacks
206→                        let n = POPUP_COUNTER.fetch_add(1, Ordering::Relaxed);
207→                        let label = format!("oauth-popup-{}", n);
208→                        match tauri::WebviewWindowBuilder::new(
209→                            &app_handle,
210→                            &label,
211→                            tauri::WebviewUrl::External("about:blank".parse().unwrap()),
212→                        )
213→                        .window_features(features)
214→                        .title(url.as_str())
215→                        .inner_size(500.0, 700.0)
216→                        .center()
217→                        .build()
218→                        {
219→                            Ok(window) => tauri::webview::NewWindowResponse::Create { window },
220→                            Err(e) => {
221→                                log::error!("Failed to create OAuth popup: {}", e);
222→                                tauri::webview::NewWindowResponse::Deny
223→                            }
224→                        }
225→                    }
226→                })
227→                .build()
228→                {
229→                    Ok(window) => {
230→                        let _ = window.show();
231→                        let _ = window.set_focus();
232→                    }
233→                    Err(e) => {
234→                        log::error!("Failed to create login window: {}", e);
235→                    }
236→                }
237→            }
238→        }
239→        "logout" => {
240→            let app_handle = app.clone();
241→            tauri::async_runtime::spawn(async move {
242→                let state = app_handle.state::<crate::state::AppState>();
243→
244→                // Unmount filesystem (FUSE on macOS, WinFsp on Windows)
245→                #[cfg(any(feature = "fuse", feature = "winfsp"))]
246→                {
247→                    if let Err(e) = crate::fuse::unmount_filesystem() {
248→                        log::warn!("Filesystem unmount during logout failed: {}", e);
249→                    }
250→                    *state.mount_status.write().await = crate::state::MountStatus::Unmounted;
251→                }
252→
253→                // POST /auth/logout (best-effort)
254→                let _ = state.sdk.api.authenticated_post("/auth/logout", &()).await;
255→
256→                // Delete refresh token from Keychain
257→                if let Some(ref user_id) = *state.sdk.user_id.read().await {
258→                    let _ = crate::keychain::delete_refresh_token(user_id);
259→                }
260→
261→                // Zero all sensitive keys
262→                state.clear_keys().await;
263→
264→                // Update tray status
265→                if let Err(e) = update_tray_status(&app_handle, &TrayStatus::NotConnected) {
266→                    log::warn!("Failed to update tray status after logout: {}", e);
267→                }
268→
269→                log::info!("Logout complete (via tray menu)");
270→            });
271→        }
272→        "quit" => {
273→            // Unmount filesystem if mounted, then exit
274→            #[cfg(any(feature = "fuse", feature = "winfsp"))]
275→            {
276→                let _ = crate::fuse::unmount_filesystem();
277→            }
278→            app.exit(0);
279→        }
280→        _ => {
281→            log::debug!("Unknown tray menu event: {}", id);
282→        }
283→    }
284→}
285→
286→/// Update the tray menu to reflect the new status.
287→///
288→/// Rebuilds the entire menu with updated item states and sets it on the tray icon.
289→/// On Error status, sends a system notification.
290→pub fn update_tray_status(app: &AppHandle, status: &TrayStatus) -> Result<(), String> {
291→    let tray = app
292→        .tray_by_id(TRAY_ID)
293→        .ok_or_else(|| "Tray icon not found".to_string())?;
294→
295→    // Rebuild the menu with updated states
296→    let menu = build_menu(app, status)?;
297→    tray.set_menu(Some(menu))
298→        .map_err(|e| format!("Failed to set tray menu: {}", e))?;
299→
300→    // Send notification on Error status
301→    if let TrayStatus::Error(ref msg) = status {
302→        if let Err(e) = send_error_notification(app, msg) {
303→            log::warn!("Failed to send error notification: {}", e);
304→        }
305→    }
306→
307→    log::debug!("Tray status updated to: {}", status.label());
308→    Ok(())
309→}
310→
311→/// Send a system notification for error states.
312→fn send_error_notification(app: &AppHandle, message: &str) -> Result<(), String> {
313→    use tauri_plugin_notification::NotificationExt;
314→    app.notification()
315→        .builder()
316→        .title("CipherBox Error")
317→        .body(message)
318→        .show()
319→        .map_err(|e| format!("Notification failed: {}", e))?;
320→    Ok(())
321→}
